"""mini_harness - minimal data processing harness."""

from mini_harness.runner import run_dag, HarnessError

__all__ = ["run_dag", "HarnessError"]
"""CLI entry point: python -m mini_harness run <files> --output <path>."""

import argparse
import json
import os
import sys

from mini_harness.runner import run_dag, load_config, HarnessError

DEFAULT_CONFIG = "config/m2.json"


def main():
    parser = argparse.ArgumentParser(prog="python -m mini_harness")
    sub = parser.add_subparsers(dest="command", required=True)

    run_parser = sub.add_parser("run", help="Run data processing")
    run_parser.add_argument("input_files", nargs="+", help="Input files (CSV / JSONL)")
    run_parser.add_argument("--output", required=True, help="Output report path")
    run_parser.add_argument(
        "--config",
        default=None,
        help=f"Config file path (JSON/YAML); defaults to {DEFAULT_CONFIG}",
    )

    args = parser.parse_args()

    if args.command == "run":
        # Resolve config path
        config_path = args.config if args.config else DEFAULT_CONFIG
        config = None
        if os.path.exists(config_path):
            try:
                config = load_config(config_path)
            except HarnessError as e:
                print(f"Config error: {e}", file=sys.stderr)
                sys.exit(1)

        try:
            result = run_dag(args.input_files, config=config)
        except HarnessError as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

        out_path = args.output
        out_dir = os.path.dirname(out_path)
        if out_dir:
            os.makedirs(out_dir, exist_ok=True)

        with open(out_path, "w", encoding="utf-8") as f:
            json.dump(result, f, ensure_ascii=False, indent=2)
        print(f"Report written to {out_path}")


if __name__ == "__main__":
    main()
"""Data processing runner: parse inputs, count processed/rejected."""

import csv
import json
import os


class HarnessError(Exception):
    """Raised when processing fails."""
    pass


def _parse_yaml(path):
    """Minimal YAML parser for simple key: value config (stdlib-only)."""
    result = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if ":" in stripped:
                key, _, value = stripped.partition(":")
                result[key.strip()] = value.strip()
    return result


def load_config(config_path):
    """Load a JSON or YAML config file based on extension.

    Returns a dict.
    """
    ext = os.path.splitext(config_path)[1].lower()
    if ext == ".json":
        with open(config_path, encoding="utf-8") as f:
            return json.load(f)
    elif ext in (".yaml", ".yml"):
        return _parse_yaml(config_path)
    else:
        raise HarnessError(f"Unsupported config file type: {config_path}")


def _read_csv(path):
    """Yield dicts from a CSV file, skipping empty rows."""
    records = []
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if all(v is None or (isinstance(v, str) and v.strip() == "") for v in row.values()):
                continue
            rec = {k.strip(): (v.strip() if v else "") for k, v in row.items()}
            records.append(rec)
    return records


def _read_jsonl(path):
    """Yield dicts from a JSONL file, skipping empty lines."""
    records = []
    with open(path, encoding="utf-8") as f:
        for line in f:
            stripped = line.strip()
            if not stripped:
                continue
            records.append(json.loads(stripped))
    return records


def _read_file(path):
    """Read a file and return list of dict records."""
    ext = os.path.splitext(path)[1].lower()
    if ext == ".csv":
        return _read_csv(path)
    elif ext == ".jsonl":
        return _read_jsonl(path)
    else:
        raise HarnessError(f"Unsupported file type: {path}")


def _get_id(record):
    """Extract id from a record (case-insensitive key lookup)."""
    for key in record:
        if key.strip().lower() == "id":
            val = record[key]
            if isinstance(val, str):
                return val.strip()
            return str(val) if val is not None else ""
    return ""


def run_dag(source_paths, config=None):
    """Process input files and return a dict with counts.

    Args:
        source_paths: list of file paths (CSV or JSONL).
        config: optional dict with config values (e.g. report_label).

    Returns:
        dict with processed_count, rejected_count, retry_count,
        source_files, and optionally report_label.

    Raises:
        HarnessError on processing failure.
    """
    processed = 0
    rejected = 0

    for path in source_paths:
        records = _read_file(path)
        for rec in records:
            record_id = _get_id(rec)
            if record_id:
                processed += 1
            else:
                rejected += 1

    result = {
        "processed_count": processed,
        "rejected_count": rejected,
        "retry_count": 0,
        "source_files": list(source_paths),
    }

    if config and "report_label" in config:
        result["report_label"] = config["report_label"]

    return result
